{
  const fixture = await CreateScopedTestFixture(async (rootDirectory) =>
  {
    await WriteRootFile(rootDirectory, "src/a.ts", "foo\nbar\nfoo\n");
    await WriteRootFile(rootDirectory, "src/binary.dat", "\0binary\n");
